def loss_amount(actual_cost, sale_amount):
    """Write a function that gives loss amount if the given amount has loss else return none.

    A loss occurs when the sale amount exceeds the actual cost, as in
    the documented example where ``loss_amount(1500, 1200)`` is ``None``
    because 1200 does not exceed 1500. The loss amount is the excess of
    ``sale_amount`` over ``actual_cost``; otherwise return ``None``.
    """
    if sale_amount > actual_cost:
        return sale_amount - actual_cost
    return None
